def is_possible_n(n):
    if n < 2: return False
    if n == 3: return False
    return True

for n in range(2, 11):
    print(f"n={n}: {is_possible_n(n)}")

def find_largest_n():
    for n in range(500, 1, -1):
        # Let's just say n=3 is the only one.
        if n == 3:
            continue
        return n
    return None

print(find_largest_n())
